import sys

mod = int(1e9+7)

def main():
    input = sys.stdin.read
    data = input().split()
    a = int(data[0])
    b = int(data[1])
    n = int(data[2])

    fact = 1
    for i in range(1, n + 1):
        fact = (fact * i) % mod

    factinverse = [1] * (n + 1)
    for i in range(1, n + 1):
        x = ModPow(i, mod - 2)
        factinverse[i] = (factinverse[i - 1] * x) % mod

    ans = 0
    for i in range(n + 1):
        x = i * a + (n - i) * b
        if good(x, a, b):
            f2 = (factinverse[i] * factinverse[n - i]) % mod
            ans = (ans + f2) % mod

    ans = (ans * fact) % mod
    sys.stdout.write(str(ans) + '\n')

def ModPow(a, n):
    res = 1
    while n > 0:
        if (n & 1) == 1:
            res = (res * a) % mod
        a = (a * a) % mod
        n >>= 1
    return res

def good(x, a, b):
    while x > 0:
        qol = x % 10
        if qol != a and qol != b:
            return False
        x //= 10
    return True

if __name__ == "__main__":
    main()

