import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class EE {
    private static BufferedReader in;
    private static StringTokenizer st;
    private static PrintWriter out;
    private static int mod;

    public static void main(String[] args) throws NumberFormatException, IOException {
        in = new BufferedReader(new InputStreamReader(System.in));
        st = new StringTokenizer("");
        out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        int a = nextInt();
        int b = nextInt();
        int n = nextInt();
        long s1 = System.currentTimeMillis();
        mod = (int) (1e9+7);
        long fact = 1;
        for (long i = 1; i <= n; i++) {
            fact = (fact * i) % mod;
        }
        long factinverse[] = new long[n+1];
        factinverse[0] = 1;
        for (int i = 1; i <=n; i++) {
            long x = ModPow(i, mod - 2);
            factinverse[i] = (factinverse[i-1] * x) % mod;
        }
        long ans = 0;
        for (int i = 0; i <=n; i++) {
            int x = i*a +(n-i)*b;
            if(good(x, a, b)){
                long f2 = (factinverse[i] * factinverse[n-i]) % mod; 
                ans = (ans + f2) % mod;
            }
        }
        ans = (ans * fact) % mod;
        long s2 = System.currentTimeMillis();
//        System.out.println((s2-s1)/1000.0);
        System.out.println(ans);
    }
    private static long ModPow(long a, int n) {
        long res = 1;
        while(n > 0){
            if((n & 1)== 1)
                res = (res * a) % mod;
            a = (a * a) % mod;
            n >>= 1;
        }
        return res;
    }
    private static boolean good(int x, int a, int b) {
        while(x > 0){
            int qol = x % 10;
            if(qol != a && qol!=b){
                return false;
            }
            x /= 10;
        }
        return true;
    }

    static String next() throws IOException{
        while(!st.hasMoreTokens()){
            st = new StringTokenizer(in.readLine());
        }
        return st.nextToken();
    }
    static int nextInt() throws NumberFormatException, IOException{
        return Integer.parseInt(next());
    }
    static long nextLong() throws NumberFormatException, IOException{
        return Long.parseLong(next());
    }

    static double nextDouble() throws NumberFormatException, IOException{
        return Double.parseDouble(next());
    }

}
